<script lang="ts">
  import X from '@lucide/svelte/icons/x';
  import ArrowUp from '@lucide/svelte/icons/arrow-up';
  import ArrowDown from '@lucide/svelte/icons/arrow-down';
  import ChevronRight from '@lucide/svelte/icons/chevron-right';
  import { api, query } from './api';
  import type { Data } from './types';
  import Receipt from './Receipt.svelte';
  export let view: string;
  let error = '', message = '', loading = false, products: Data[] = [], categories: Data[] = [], chosen: string[] = [], periods: Data[] = [], report: Data = {}, member: Data | null = null, memberItems: Data[] = [], invoice: Data | null = null;
  let edit: Data | null = null, search = '', period = '', page = 1, more = false;
  let lastView = '', orderCategory = '', memberPage = 1, memberMore = false;
  let soList: Data[] = [], soYear = new Date().getFullYear(), soMore = false, soPage = 1, soDetail: Data | null = null, draft: Data[] = [], draftKey = '', counting = false, cari = '', hasil: Data[] = [], savingSo = false;
  let hargaTotal = 0, stokTotal = 0, kontrolStok = true, opname: Data | null = null, qty = '', saving = false, opnameKey = '';
  const rp = (n: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(n || 0);
  $: if (view !== lastView) { lastView = view; products = []; search = ''; page = 1; more = false; message = ''; if (typeof window !== 'undefined') load(); }
  async function load(next = false) { loading = true; error = ''; try {
    if (view === 'produk') { const p = next ? page + 1 : 1; const result = await api<Data>('/admin/produk' + query({ q: search, page: p, size: 100 })); products = next ? [...products, ...result.items] : result.items; page = p; more = result.ada_lagi; categories = await api('/admin/kategori'); }
    if (view === 'opname') { const p = next ? soPage + 1 : 1; const result = await api<Data>('/admin/stok-opname' + query({ tahun: soYear, page: p, size: 50 })); soList = next ? [...soList, ...result.items] : result.items; soPage = p; soMore = result.ada_lagi; }
    if (view === 'harga') { const p = next ? page + 1 : 1; const result = await api<Data>('/admin/produk' + query({ q: search, page: p, size: 100, harga_rendah: 'Y' })); products = next ? [...products, ...result.items] : result.items; page = p; more = result.ada_lagi; if (result.jumlah != null) hargaTotal = result.jumlah; categories = await api('/admin/kategori'); }
    if (view === 'stok') { const p = next ? page + 1 : 1; const result = await api<Data>('/admin/stok-habis' + query({ q: search, page: p, size: 100 })); products = next ? [...products, ...result.items] : result.items; page = p; more = result.ada_lagi; if (result.jumlah != null) stokTotal = result.jumlah; kontrolStok = result.kontrol_stok !== false; }
    if (view === 'urut') { categories = await api('/admin/kategori'); const visible = await api<string[]>('/admin/kategori-tampil'); if (visible.length) categories = categories.filter(c => visible.includes(c.id)); if (!orderCategory || !categories.some(c => c.id === orderCategory)) orderCategory = categories[0]?.id || ''; products = []; more = false; if (orderCategory) { for (let p = 1; p <= 10; p++) { const result = await api<Data>('/admin/produk' + query({ kategori: orderCategory, aktif: 'Y', page: p, size: 100 })); products = [...products, ...result.items]; more = result.ada_lagi; if (!more) break; } } }
    if (view === 'kategori') { categories = await api('/admin/kategori'); chosen = await api('/admin/kategori-tampil'); }
    if (view === 'rekap') { const ps = await api<Data>('/admin/periode'); periods = ps.items; if (!period && (ps.sekarang || ps.items[0])) period = String(ps.sekarang || ps.items[0].periode); report = await api('/admin/rekap-anggota' + query({ periode: period })); }
  } catch (e) { error = (e as Error).message; } finally { loading = false; } }
  async function run(f: () => Promise<unknown>, notice = 'Berhasil disimpan.') { error = ''; try { await f(); message = notice; await load(); } catch (e) { error = (e as Error).message; } }
  async function saveProduct() { if (!edit) return; const p = edit; await run(() => api('/admin/produk/' + p.id, { method:'PUT', body: { nama:p.nama, barcode:p.barcode, satuan:p.satuan, kategori_id:p.kategori_id, harga:Number(p.harga), beli:Number(p.beli), aktif:p.aktif } })); if (!error) edit = null; }
  async function upload(e: Event, id: number) { const file = (e.currentTarget as HTMLInputElement).files?.[0]; if (file) await run(() => api('/admin/produk/' + id + '/foto', {method:'PUT',body:file,headers:{'Content-Type':'application/octet-stream'}}), 'Foto disimpan.'); }
  function startCount() { counting = true; draft = []; hasil = []; cari = ''; draftKey = crypto.randomUUID(); error = ''; message = ''; }
  async function searchStok() { error = ''; try { const r = await api<Data>('/admin/stok' + query({ q: cari, page: 1, size: 20 })); hasil = r.items; const q = cari.trim(); const exact = hasil.filter(p => p.barcode && p.barcode === q); if (exact.length === 1) { addDraft(exact[0]); cari = ''; hasil = []; } } catch (e) { error = (e as Error).message; } }
  function addDraft(p: Data) { if (draft.some(d => d.id === p.id)) { error = p.nama + ' sudah ada di daftar hitung.'; return; } error = ''; draft = [...draft, { ...p, qty: '' }]; }
  function removeDraft(i: number) { draft = draft.filter((_, j) => j !== i); }
  async function saveSo() { if (savingSo || !draft.length) return; const items = []; for (const d of draft) { const n = Number(String(d.qty).replace(',', '.')); if (String(d.qty).trim() === '' || !Number.isFinite(n) || n < 0) { error = 'Qty fisik ' + d.nama + ' belum valid.'; return; } items.push({ produk_id: d.id, qty_fisik: n }); } const total = draft.reduce((a, d) => a + Math.abs(Number(String(d.qty).replace(',', '.')) - Number(d.stok)), 0); if (!confirm('Simpan dokumen SO untuk ' + items.length + ' barang?\nTotal selisih mutlak ' + total + '.\nDokumen SO tidak dapat dibatalkan dari web.')) return; savingSo = true; error = ''; try { const r = await api<Data>('/admin/stok-opname/dokumen', { method: 'POST', headers: { 'Idempotency-Key': draftKey }, body: { items } }); counting = false; message = 'Dokumen ' + r.nomor_so + ' tersimpan (' + r.items.length + ' barang).'; await load(); } catch (e) { error = (e as Error).message; } finally { savingSo = false; } }
  async function openSo(no: string) { error = ''; try { soDetail = await api<Data>('/admin/stok-opname/' + encodeURIComponent(no)); } catch (e) { error = (e as Error).message; } }
  function openOpname(p: Data) { opname = p; qty = ''; error = ''; message = ''; opnameKey = crypto.randomUUID(); }
  async function saveOpname() { if (!opname || saving) return; const n = Number(qty); if (qty.trim() === '' || !Number.isFinite(n) || n < 0) { error = 'Qty fisik tidak valid.'; return; } const o = opname; if (!confirm('Koreksi stok ' + o.nama + '?\nStok sistem ' + o.stok + ' → stok fisik ' + n + ' (selisih ' + (n - Number(o.stok)) + ').\nDokumen SO tidak dapat dibatalkan dari web.')) return; saving = true; error = ''; try { const r = await api<Data>('/admin/stok-opname', { method: 'POST', headers: { 'Idempotency-Key': opnameKey }, body: { produk_id: o.id, qty_fisik: n } }); opname = null; message = 'Opname ' + r.nomor_so + ' tersimpan (selisih ' + r.selisih + ').'; await load(); } catch (e) { error = (e as Error).message; } finally { saving = false; } }
  function move(i: number, delta: number) { const j = i + delta; if (j < 0 || j >= products.length) return; [products[i], products[j]] = [products[j], products[i]]; products = [...products]; }
  async function openMember(m: Data, next = false) { try { member = m; const p = next ? memberPage + 1 : 1; const result = await api<Data>('/admin/rekap-anggota/' + encodeURIComponent(m.nik) + '/transaksi' + query({periode:period,page:p,size:100})); memberItems = next ? [...memberItems, ...result.items] : result.items; memberPage = p; memberMore = result.ada_lagi; } catch(e) { error = (e as Error).message; } }
  async function showInvoice(no: string) { try { invoice = await api('/admin/faktur/' + encodeURIComponent(no)); } catch(e) { error = (e as Error).message; } }
</script>
{#if error}<div class="error" role="alert">{error}</div>{/if}{#if message}<div class="notice">{message}</div>{/if}{#if loading}<p class="muted">Memuat data…</p>{/if}
<section class="panel"><div class="section-heading"><div><p class="eyebrow">ADMINISTRASI</p><h2>{view === 'produk' ? 'Katalog produk' : view === 'stok' ? 'Stok habis' : view === 'harga' ? 'Harga jual ≤ HPP' : view === 'opname' ? 'Stock opname' : view === 'kategori' ? 'Kategori tampil' : view === 'urut' ? 'Urutan produk' : 'Rekap anggota'}</h2></div></div>
{#if view === 'produk' || view === 'urut'}{#if view === 'produk'}<form class="search" on:submit|preventDefault={() => load()}><input bind:value={search} placeholder="Cari produk"/><button>Cari</button></form>{:else}<label>Kategori<select bind:value={orderCategory} on:change={() => load()}>{#each categories as c}<option value={c.id}>{c.nama}</option>{/each}</select></label><p class="muted">Urutkan seluruh produk aktif dalam kategori ini.</p>{#if more}<div class="error">Kategori memiliki lebih dari 1.000 produk dan tidak dapat diurutkan di sini.</div>{/if}{/if}{#each products as p, i}<div class="admin-row"><div><strong>{p.nama}</strong><small>{p.kode} · {p.kategori} · {rp(p.harga)} · {p.aktif ? 'Aktif' : 'Nonaktif'}</small></div><div class="actions">{#if view === 'produk'}<button on:click={() => edit = {...p}}>Ubah</button>{:else}<button aria-label="Naikkan" on:click={() => move(i,-1)} disabled={i === 0}><ArrowUp size={16} aria-hidden="true"/></button><button aria-label="Turunkan" on:click={() => move(i,1)} disabled={i === products.length-1}><ArrowDown size={16} aria-hidden="true"/></button>{/if}</div></div>{/each}{#if more && view === 'produk'}<button class="secondary" on:click={() => load(true)}>Muat lebih banyak</button>{/if}{#if view === 'urut' && products.length && !more}<button class="primary" on:click={() => run(() => api('/admin/produk-urut',{method:'PUT',body:{produk_ids:products.map(p => p.id)}}))}>Simpan urutan</button>{/if}
{:else if view === 'opname'}{#if counting}<div class="row"><h3>Opname baru</h3><button on:click={() => counting = false}>Batal</button></div><form class="search" on:submit|preventDefault={searchStok}><input bind:value={cari} placeholder="Cari nama, kode, atau scan barcode"/><button>Cari</button></form>{#each hasil as p}<div class="admin-row"><div><strong>{p.nama}</strong><small>{p.kode} · stok sistem {p.stok} {p.satuan}</small></div><div class="actions"><button on:click={() => addDraft(p)}>Tambah</button></div></div>{/each}<h3>Daftar hitung ({draft.length})</h3>{#each draft as d, i}<div class="admin-row"><div><strong>{d.nama}</strong><small>{d.kode} · sistem {d.stok} {d.satuan}{#if String(d.qty).trim() !== '' && Number.isFinite(Number(String(d.qty).replace(',', '.')))} · selisih {Number(String(d.qty).replace(',', '.')) - Number(d.stok)}{/if}</small></div><div class="actions"><input bind:value={d.qty} inputmode="decimal" placeholder="Qty fisik" style="width:7rem"/><button on:click={() => removeDraft(i)} aria-label="Hapus"><X size={20} aria-hidden="true"/></button></div></div>{:else}<p class="muted">Cari barang lalu tekan Tambah, atau scan barcode lalu Enter.</p>{/each}<button class="primary" disabled={!draft.length || savingSo} on:click={saveSo}>{savingSo ? 'Menyimpan…' : 'Simpan SO'}</button>{:else}<div class="row"><label>Tahun<input type="number" bind:value={soYear} min="2000" max="2100" on:change={() => load()}/></label><button class="primary" on:click={startCount}>Opname baru</button></div>{#each soList as s}<div class="admin-row"><div><strong>{s.nomor_so}</strong><small>{s.tanggal} · {s.jumlah_item} barang · nilai selisih {rp(s.nilai_selisih)}</small></div><div class="actions"><button on:click={() => openSo(s.nomor_so)}>Detail</button></div></div>{:else}{#if !loading}<p class="muted">Belum ada dokumen SO pada tahun ini.</p>{/if}{/each}{#if soMore}<button class="secondary" on:click={() => load(true)}>Muat lebih banyak</button>{/if}{/if}
{:else if view === 'harga'}<form class="search" on:submit|preventDefault={() => load()}><input bind:value={search} placeholder="Cari produk"/><button>Cari</button></form><p class="muted">{hargaTotal} produk aktif dengan harga jual ≤ harga beli (HPP). Produk tanpa harga beli tidak ditampilkan.</p>{#each products as p}<div class="admin-row"><div><strong>{p.nama}</strong><small>{p.kode} · {p.kategori} · jual {rp(p.harga)} · beli {rp(p.beli)} · margin <span class="margin-neg" style="color: var(--danger, #b3261e)">{rp(p.harga - p.beli)}</span></small></div><div class="actions"><button on:click={() => edit = {...p}}>Ubah</button></div></div>{:else}{#if !loading}<p class="muted">Tidak ada produk dengan harga jual ≤ HPP.</p>{/if}{/each}{#if more}<button class="secondary" on:click={() => load(true)}>Muat lebih banyak</button>{/if}
{:else if view === 'stok'}<form class="search" on:submit|preventDefault={() => load()}><input bind:value={search} placeholder="Cari produk"/><button>Cari</button></form><p class="muted">{stokTotal} produk aktif dengan stok sistem ≤ 0. Isi hasil hitung fisik untuk mengoreksi stok.</p>{#if !kontrolStok}<div class="notice">Kontrol stok di kasir nonaktif (KONTROL_SALDO_QTY = 0): daftar ini dapat memuat barang yang memang tidak dilacak stoknya.</div>{/if}{#each products as p}<div class="admin-row"><div><strong>{p.nama}</strong><small>{p.kode} · {p.kategori} · stok {p.stok} {p.satuan}</small></div><div class="actions"><button on:click={() => openOpname(p)}>Opname</button></div></div>{:else}{#if !loading}<p class="muted">Tidak ada barang dengan stok habis.</p>{/if}{/each}{#if more}<button class="secondary" on:click={() => load(true)}>Muat lebih banyak</button>{/if}
{:else if view === 'kategori'}<p class="muted">Jika tidak ada kategori yang dipilih, semua kategori ditampilkan.</p>{#each categories as c}<label class="check"><input type="checkbox" value={c.id} bind:group={chosen}/>{c.nama}</label>{/each}<button class="primary" on:click={() => run(() => api('/admin/kategori-tampil',{method:'PUT',body:{kategori_ids:chosen}}))}>Simpan kategori</button>
{:else if view === 'rekap'}<label>Periode<select bind:value={period} on:change={() => load()}>{#each periods as p}<option value={String(p.periode)}>{p.periode} · {p.dari} – {p.sampai}</option>{/each}</select></label><p>Total: <strong>{rp(report.total)}</strong> · {report.jumlah_transaksi || 0} transaksi</p>{#each report.items || [] as m}<button class="list-button horizontal" on:click={() => openMember(m)}><span><strong>{m.nama}</strong><small>{m.nik} · {m.unit} · {m.jumlah} transaksi</small></span><strong>{rp(m.total)} <ChevronRight size={16} class="chev" aria-hidden="true"/></strong></button>{/each}{/if}</section>
{#if soDetail}<div class="overlay"><section class="modal" role="dialog" aria-modal="true"><div class="row"><h2>{soDetail.nomor_so}</h2><button aria-label="Tutup" class="icon" on:click={() => soDetail = null}><X size={20} aria-hidden="true"/></button></div><p class="muted">{soDetail.tanggal}</p>{#each soDetail.items as b}<div class="admin-row"><div><strong>{b.nama}</strong><small>{b.kode} · sistem {b.jumlah_sistem} → fisik {b.qty_fisik} · selisih {b.selisih}</small></div></div>{/each}</section></div>{/if}
{#if opname}<div class="overlay"><section class="modal" role="dialog" aria-modal="true"><div class="row"><h2>Opname stok</h2><button aria-label="Tutup" class="icon" on:click={() => opname = null}><X size={20} aria-hidden="true"/></button></div>{#if error}<div class="error">{error}</div>{/if}<p><strong>{opname.nama}</strong><br/><small>{opname.kode} · stok sistem {opname.stok} {opname.satuan}</small></p><form on:submit|preventDefault={saveOpname}><label>Qty fisik<input bind:value={qty} inputmode="decimal" required placeholder="0"/></label><button class="primary" disabled={saving}>{saving ? 'Menyimpan…' : 'Simpan opname'}</button></form></section></div>{/if}
{#if edit}<div class="overlay"><section class="modal"><div class="row"><h2>Ubah produk</h2><button aria-label="Tutup" class="icon" on:click={() => edit = null}><X size={20} aria-hidden="true"/></button></div>{#if error}<div class="error">{error}</div>{/if}<form on:submit|preventDefault={saveProduct}><label>Nama<input bind:value={edit.nama} required/></label><label>Barcode<input bind:value={edit.barcode}/></label><label>Satuan<input bind:value={edit.satuan} required/></label><label>Kategori<select bind:value={edit.kategori_id}>{#each categories as c}<option value={c.id}>{c.nama}</option>{/each}</select></label><label>Harga jual<input type="number" bind:value={edit.harga} min="0" required/></label><label>Harga beli<input type="number" bind:value={edit.beli} min="0" required/></label><label class="check"><input type="checkbox" bind:checked={edit.aktif}/> Aktif</label><button class="primary">Simpan</button></form><label>Foto produk (JPEG/PNG, maks. 1 MB)<input type="file" accept="image/jpeg,image/png" on:change={(e) => upload(e, edit!.id)}/></label><button on:click={() => run(() => api('/admin/produk/' + edit!.id + '/foto',{method:'DELETE'}),'Foto dihapus.')}>Hapus foto</button></section></div>{/if}
{#if member}<div class="overlay"><section class="modal"><div class="row"><h2>{member.nama}</h2><button aria-label="Tutup" class="icon" on:click={() => member = null}><X size={20} aria-hidden="true"/></button></div><p>{member.nik} · {rp(member.total)}</p>{#each memberItems as t}<button class="list-button horizontal" on:click={() => showInvoice(t.no_transaksi)}><span>{t.no_transaksi}<small>{t.tanggal}</small></span><strong>{rp(t.total)} <ChevronRight size={16} class="chev" aria-hidden="true"/></strong></button>{:else}<p class="empty">Tidak ada transaksi.</p>{/each}{#if memberMore}<button class="secondary wide" on:click={() => openMember(member!, true)}>Muat lebih banyak</button>{/if}</section></div>{/if}
{#if invoice}<Receipt {invoice} close={() => invoice = null}/>{/if}
